<script setup lang="ts">
import { tx } from '@/i18n'
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import auth from '@/plugins/auth'
import { agentDateLabel, agentStatusLabel, emptyAgentPage, formatMoney, formatPoints, privateTrackingUrl, useAgentApi, useAgentActions, type AgentBatch, type AgentOrder, type AgentAdmission, type AgentOrderCreditQuote } from '../lib/agentWorkbench'
import AgentPagination from './AgentPagination.vue'
import AgentPrivatePhoto from './AgentPrivatePhoto.vue'
import NxrCardIdentityPanel from '@/components/NxrCardIdentityPanel.vue'
const api = useAgentApi(), route = useRoute(), rows = ref(emptyAgentPage<AgentBatch>()), batch = ref<AgentBatch | null>(null)
const order = ref<AgentOrder | null>(null), admission = ref<AgentAdmission | null>(null), creditQuote = ref<AgentOrderCreditQuote | null>(null), accepted = ref(false), loading = ref(false), orderLoading = ref(false)
const packingSlip = ref<Awaited<ReturnType<typeof api.fetchPackingSlip>> | null>(null)
const supplementNote = ref(''), supplementPhotos = ref<number[]>([])
const trackingLinks = ref<Record<string,string>>({}), revokedLinks = ref<Record<string,boolean>>({})
const shipment = reactive({ carrierName:'',trackingNumber:'',note:'' }), { busy,error,success,run } = useAgentActions()
const canInbound = computed(() => Boolean(batch.value?.orders?.length && batch.value.orders.every(item => ['awaiting_inbound','inbound_shipped'].includes(item.statusCode))))
const financeAllowed = computed(() => auth.hasPermi('nxr:customer:finance'))
const available = computed(() => creditQuote.value?.balance || 0)
let generation = 0, orderGeneration = 0
async function load(page = 1) { loading.value=true; try { rows.value = await api.fetchBatches(page) } catch(e) { error.value=e instanceof Error?e.message:tx('Unable to load batches.') } finally {loading.value=false} }
async function openBatch(batchNo: string) {
  if(busy.value)return
  trackingLinks.value={};revokedLinks.value={}
  const current=++generation; orderGeneration++; batch.value=null; order.value=null; admission.value=null; packingSlip.value=null; orderLoading.value=false; loading.value=true; error.value=''
  try { const value=await api.fetchBatch(batchNo);if(current===generation)batch.value=value }
  catch(e){if(current===generation)error.value=e instanceof Error?e.message:tx('Unable to load batch details.')}
  finally{if(current===generation)loading.value=false}
}
async function openOrder(orderNo: string) {
  if(busy.value)return
  const current=++orderGeneration;creditQuote.value=null;orderLoading.value=true;order.value=null;admission.value=null;packingSlip.value=null;accepted.value=false;supplementNote.value='';supplementPhotos.value=[];error.value=''
  try { const [record,review]=await Promise.all([api.fetchOrder(orderNo),api.fetchAdmission(orderNo)]);if(current===orderGeneration){order.value=record;review.canPay=review.canPay&&financeAllowed.value;admission.value=review;if(review.canPay){const quoted=await api.fetchOrderCreditQuote(orderNo);if(current===orderGeneration)creditQuote.value=quoted}} }
  catch(e){if(current===orderGeneration)error.value=e instanceof Error?e.message:tx('Unable to load order details.')}
  finally{if(current===orderGeneration)orderLoading.value=false}
}
async function refreshCurrent() { try{if(order.value)await openOrder(order.value.orderNo);if(batch.value)batch.value=await api.fetchBatch(batch.value.batchNo);await load(rows.value.page)}catch(e){if(api.isActive())error.value=e instanceof Error?e.message:tx('Changes saved. Refresh to see the latest status.')} }
async function acceptTerms() {
  if(!order.value||!admission.value?.canAcceptTerms||!accepted.value)return
  const no=order.value.orderNo,payload={termsVersion:admission.value.termsVersion,acceptedQuotedAmount:Number(admission.value.quoteAmount),acceptedCurrency:admission.value.quoteCurrency}
  if(await run(`order:${no}:terms`,payload,key=>api.acceptOrderTerms(no,payload,key),value=>{admission.value=value},tx('Order and service terms confirmed.')))await refreshCurrent()
}
async function pay() {
  if (!financeAllowed.value) return
  if(!order.value||!admission.value?.canPay||!creditQuote.value?.sufficient||orderLoading.value)return
  const no=order.value.orderNo,payload={orderNo:no,amount:order.value.totalAmount,currency:order.value.currencyCode,settingsVersion:creditQuote.value.quote.settingsVersion,expectedPoints:String(creditQuote.value.quote.points)}
  if(await run(`order:${no}:pay`,payload,key=>api.payFromWallet(no,key,payload.settingsVersion,payload.expectedPoints),value=>{order.value=value},tx('Order paid using enterprise credits.')))await refreshCurrent();else creditQuote.value=null
}
async function inbound() {
  if(!batch.value||!canInbound.value)return
  const no=batch.value.batchNo,payload={...shipment,direction:'inbound',directionCode:'inbound'}
  if(await run(`batch:${no}:inbound`,payload,key=>api.addBatchInbound(no,payload,key),()=>{shipment.carrierName='';shipment.trackingNumber='';shipment.note=''},tx('Main parcel to NXR recorded.')))await refreshCurrent()
}
async function uploadSupplement(event:Event){
  const input=event.target as HTMLInputElement,file=input.files?.[0]
  if(!file||!order.value)return
  if(!['image/jpeg','image/png'].includes(file.type)||file.size>15*1024*1024){error.value=tx('Choose a JPG or PNG file no larger than 15 MB.');input.value='';return}
  await run(`order:${order.value.orderNo}:photo`,{name:file.name,size:file.size,lastModified:file.lastModified},()=>api.uploadSupplementalPhoto(file),value=>{supplementPhotos.value.push(value.id)},tx('Additional photo uploaded.'))
  input.value=''
}
async function resubmit(){if(!order.value||!admission.value?.canResubmit)return;const no=order.value.orderNo,payload={note:supplementNote.value.trim(),supplementalPhotoIds:[...supplementPhotos.value]};if(await run(`order:${no}:resubmit`,payload,key=>api.resubmitOrder(no,payload,key),value=>{admission.value=value},tx('Additional information submitted for review.')))await refreshCurrent()}
async function rotateLink(orderNo:string){
  if(!batch.value)return
  const batchNo=batch.value.batchNo
  await run(`tracking:${batchNo}:${orderNo}:rotate`,{batchNo,orderNo},()=>api.rotateTrackingLink(batchNo,orderNo),value=>{trackingLinks.value[orderNo]=privateTrackingUrl(value.trackingUrl);revokedLinks.value[orderNo]=false},tx('Customer tracking link updated. The previous link is no longer valid.'))
}
async function revokeLink(orderNo:string){
  if(!batch.value)return
  const batchNo=batch.value.batchNo
  await run(`tracking:${batchNo}:${orderNo}:revoke`,{batchNo,orderNo},()=>api.revokeTrackingLink(batchNo,orderNo),()=>{delete trackingLinks.value[orderNo];revokedLinks.value[orderNo]=true},tx('Customer tracking link revoked.'))
}
async function copyLink(orderNo:string){const link=trackingLinks.value[orderNo];if(!link)return;try{await navigator.clipboard.writeText(link);success.value=tx('Customer tracking link copied.')}catch{error.value=tx('The browser did not allow copying. Select the link and copy it manually.')}}
async function loadPackingSlip(){if(!order.value)return;try{packingSlip.value=await api.fetchPackingSlip(order.value.orderNo)}catch(e){error.value=e instanceof Error?e.message:tx('Unable to load intake information.')}}
async function followRoute(){if(typeof route.query.batch==='string')await openBatch(route.query.batch);if(typeof route.query.order==='string')await openOrder(route.query.order)}
watch(()=>[route.query.batch,route.query.order],followRoute)
onMounted(async()=>{await load();await followRoute()})
</script>
<template><section data-testid="agent-batches-panel"><div class="agent-toolbar"><h2>{{ $tx('Submission batches') }}</h2><el-button :loading="loading" :disabled="busy" @click="load()">{{ $tx('Refresh batch') }}</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-alert v-if="success" :title="success" type="success" :closable="false" /><div class="agent-batch-grid"><button v-for="item in rows.items" :key="item.batchNo" type="button" class="agent-record" :class="{selected:batch?.batchNo===item.batchNo}" :disabled="busy" @click="openBatch(item.batchNo)"><strong>{{ item.batchName || item.batchNo }}</strong><span>{{ item.batchNo }}</span><span>{{ agentStatusLabel(item.statusCode) }}</span></button></div><el-empty v-if="!rows.items.length&&!loading" :description="$tx('No submission batches yet. Check customer intakes into inventory first.')" /><AgentPagination v-bind="rows" :disabled="loading||busy" @change="load" />
  <template v-if="batch"><div class="agent-toolbar"><h3>{{ batch.batchNo }}</h3><span>{{ agentStatusLabel(batch.statusCode) }}</span></div><el-table :data="batch.orders||[]" border><el-table-column prop="clientReference" :label="$tx('Customer reference')" min-width="150" /><el-table-column prop="clientDisplayName" :label="$tx('Customer')" min-width="130" /><el-table-column :label="$tx('Order')" min-width="190"><template #default="{row}"><el-button link type="primary" :disabled="busy" :data-testid="`agent-open-order-${row.orderNo}`" @click="openOrder(row.orderNo)">{{row.orderNo}}</el-button></template></el-table-column><el-table-column :label="$tx('Cards')" width="80"><template #default="{row}">{{row.totalCardCount??row.cardCount}}</template></el-table-column><el-table-column :label="$tx('Status')" min-width="140"><template #default="{row}">{{agentStatusLabel(row.statusCode==='admission_review'&&row.admissionStatus?row.admissionStatus:row.statusCode)}}</template></el-table-column><el-table-column :label="$tx('Private customer tracking')" min-width="260"><template #default="{row}"><div class="tracking-actions"><el-button link type="primary" :disabled="busy" :data-testid="`submission-tracking-create-${row.orderNo}`" @click="rotateLink(row.orderNo)">{{trackingLinks[row.orderNo]?$tx('Replace link'):$tx('Create link')}}</el-button><el-button v-if="trackingLinks[row.orderNo]" link :disabled="busy" :data-testid="`submission-tracking-copy-${row.orderNo}`" @click="copyLink(row.orderNo)">{{ $tx('Copy') }}</el-button><el-button v-if="(trackingLinks[row.orderNo]||row.trackingTokenHint)&&!revokedLinks[row.orderNo]" link type="danger" :disabled="busy" :data-testid="`submission-tracking-revoke-${row.orderNo}`" @click="revokeLink(row.orderNo)">{{ $tx('Revoke') }}</el-button><span v-if="revokedLinks[row.orderNo]">{{ $tx('Revoked') }}</span></div><el-input v-if="trackingLinks[row.orderNo]" :model-value="trackingLinks[row.orderNo]" readonly :aria-label="$tx('Private customer tracking link')" @focus="($event.target as HTMLInputElement).select()" /></template></el-table-column></el-table><p class="muted-copy">{{ $tx('The link shows only this customer\'s order progress. Replacing the link invalidates the previous one. Share it only with the intended customer.') }}</p><h3>{{ $tx('Main parcel tracking') }}</h3><p v-if="!batch.shipments?.length" class="muted-copy">{{ $tx('No shipment tracking recorded yet.') }}</p><el-table v-else :data="batch.shipments" border><el-table-column :label="$tx('Direction')" width="130"><template #default="{row}">{{row.directionCode==='inbound'?$tx('Ship to NXR'):$tx('NXR return to sub-agent')}}</template></el-table-column><el-table-column prop="carrierName" :label="$tx('Carrier')" /><el-table-column prop="trackingNumber" :label="$tx('Tracking number')" min-width="180" /><el-table-column :label="$tx('Status')"><template #default="{row}">{{agentStatusLabel(row.statusCode)}}</template></el-table-column></el-table><form v-if="canInbound" class="portal-form agent-operation" @submit.prevent="inbound"><h3>{{ $tx('Register main parcel to NXR') }}</h3><div class="form-grid"><label>{{ $tx('Carrier') }}<input v-model="shipment.carrierName" required maxlength="128" :disabled="busy" /></label><label>{{ $tx('Tracking number') }}<input v-model="shipment.trackingNumber" required maxlength="128" :disabled="busy" /></label></div><button class="btn-primary" :disabled="busy" data-testid="agent-save-batch-inbound">{{ $tx('Save main parcel tracking') }}</button></form></template>
  <p v-if="orderLoading" role="status">{{ $tx('Loading order…') }}</p><section v-if="order&&admission" class="agent-order-detail" data-testid="agent-order-detail"><div class="agent-toolbar"><h3>{{ $tx('Order {p1}', { p1: order.orderNo }) }}</h3><el-button :disabled="busy" @click="openOrder(order.orderNo)">{{ $tx('Refresh order') }}</el-button></div><div class="agent-quote"><strong>{{ $tx('{p1} · {p2} cards', { p1: formatMoney(order.totalAmount,order.currencyCode), p2: order.totalCardCount }) }}</strong><span>{{agentStatusLabel(admission.admissionStatus||order.statusCode)}}</span><span v-if="admission.paymentDueAtIso">{{ $tx('Payment due: {p1}', { p1: agentDateLabel(admission.paymentDueAtIso) }) }}</span><span v-if="admission.decisionNote">{{ $tx('Review notes: {p1}', { p1: admission.decisionNote }) }}</span></div><form v-if="admission.canResubmit" class="portal-form agent-operation" @submit.prevent="resubmit"><h3>{{ $tx('Provide additional application information') }}</h3><label>{{ $tx('Additional information') }}<textarea v-model="supplementNote" required maxlength="2000" :disabled="busy" /></label><label>{{ $tx('Additional photos (optional)') }}<input type="file" accept="image/jpeg,image/png" :disabled="busy" @change="uploadSupplement" /></label><div><AgentPrivatePhoto v-for="id in supplementPhotos" :key="id" :photo-id="id" :label="$tx('Additional photo')" /></div><button class="btn-primary" :disabled="busy" data-testid="agent-resubmit-order">{{ $tx('Submit additional information') }}</button></form><form v-if="admission.canAcceptTerms" class="portal-form agent-operation" @submit.prevent="acceptTerms"><h3>{{ $tx('Confirm quote and service terms') }}</h3><p class="agent-terms">{{admission.termsText}}</p><label class="agent-checkbox"><input v-model="accepted" type="checkbox" required :disabled="busy" data-testid="agent-accept-terms-checkbox" />{{ $tx('I have read and accept the current quote and service terms') }}</label><button class="btn-primary" :disabled="busy||!accepted" data-testid="agent-accept-order-terms">{{ $tx('Accept terms') }}</button></form><div v-if="admission.canPay" class="agent-operation"><p>{{ $tx('Available enterprise credits') }}: {{formatPoints(available)}}</p><p v-if="creditQuote">{{formatMoney(creditQuote.quote.sourceAmount,creditQuote.quote.sourceCurrency)}} → {{formatPoints(creditQuote.quote.points)}} · {{$tx('Rate version {version}',{version:creditQuote.quote.settingsVersion})}}</p><p v-else>{{$tx('Refresh the order to obtain a credit quote before payment.')}}</p><el-button type="primary" :disabled="busy||orderLoading||!creditQuote?.sufficient" data-testid="agent-pay-order-wallet" @click="pay">{{ $tx('Pay with enterprise credits') }}</el-button><router-link :to="{path:'/nxr/submission-workbench',query:{tab:'wallet',company:api.companyId}}">{{ $tx('View credits / top up') }}</router-link></div><NxrCardIdentityPanel :key="order.orderNo" :order-no="order.orderNo" :company-id="api.companyId" /><h3>{{ $tx('Order cards') }}</h3><div class="agent-inventory-cards"><article v-for="card in order.items" :key="card.id" class="agent-stock-card"><strong>{{card.cardName}}</strong><p>{{card.languageCode}} · {{agentStatusLabel(card.statusCode)}}</p><p v-if="card.gradingCertId">{{ $tx('Certificate ID: {p1}', { p1: card.gradingCertId }) }}</p><AgentPrivatePhoto :photo-id="card.frontPhotoId" :label="$tx('Front')" /><AgentPrivatePhoto :photo-id="card.backPhotoId" :label="$tx('Back')" /></article></div><el-button class="agent-spacing" :disabled="busy" @click="loadPackingSlip">{{ $tx('View packing slip details') }}</el-button><div v-if="packingSlip" class="agent-quote"><strong>{{ $tx('{p1} · {p2} cards', { p1: packingSlip.orderNo, p2: packingSlip.totalCardCount }) }}</strong><span>{{ $tx('Intake code: {p1}', { p1: packingSlip.intakeCode }) }}</span><span>{{ $tx('Packing slip: {p1}', { p1: packingSlip.packingSlipCode }) }}</span><p v-for="line in packingSlip.packingInstructions" :key="line">{{line}}</p></div><h3>{{ $tx('Order progress') }}</h3><ol class="agent-timeline"><li v-for="event in order.timeline" :key="event.id"><div><strong>{{event.title}}</strong><time>{{agentDateLabel(event.createdAt)}}</time></div><p v-if="event.detail">{{event.detail}}</p></li></ol></section>
</section></template>
